"""Which name means which step."""

from pipeline.steps import Squeeze, Strip, Truncate, Upper

STEPS = {"upper": Upper(), "strip": Strip(), "squeeze": Squeeze()}


def lookup(name: str):
    if ":" in name:
        step_name, arg_str = name.split(":", 1)
        if not arg_str:
            raise ValueError(f"missing argument for step {step_name!r} in {name!r}")
        try:
            length = int(arg_str)
        except ValueError:
            raise ValueError(
                f"invalid integer argument {arg_str!r} for step {step_name!r}"
            )
        return Truncate(length)
    if name not in STEPS:
        raise KeyError(f"no step named {name!r}. Known: {', '.join(sorted(STEPS))}")
    return STEPS[name]

